import { ConfigPlugin } from '@znight/config'
import { Application } from '@znight/core'
import { HttpPlugin } from '@znight/http'
import { ObservabilityPlugin } from '@znight/observability'
import { OpenApiPlugin } from '@znight/openapi'

// Generated by the compiler (znight generate, vite build, bun test): every provider, its
// dependencies, the route table and the OpenAPI operations. Only this file imports it.
import { __ZNIGHT_METADATA__ } from './.znight/container.generated.js'
import { ServerConfig } from './config/server.config.js'
import { httpOptions, openApiOptions } from './http.js'

/**
 * In production, serve the document written by `znight build` next to the bundle
 * (`dist/openapi.json`, equal to the committed `openapi.json`) instead of assembling it at boot.
 */
const document = process.env.NODE_ENV === 'production' ? { file: new URL('./openapi.json', import.meta.url) } : 'build'

const app = await Application.create({
  metadata: __ZNIGHT_METADATA__,
  plugins: [
    // First, so that its hooks wrap everything else: one JSON log line per request (with its
    // requestId), traces. Options may be computed from config classes: the function runs once
    // ConfigPlugin has loaded the configuration. Health checks and documentation requests are not
    // logged. Metrics need the optional `prom-client`, which this example does not install
    // (examples/rest-api shows them): `false` says so explicitly.
    ObservabilityPlugin.configure(container => ({
      logging: {
        level: container.get(ServerConfig).logLevel,
        requests: {
          ignore: event =>
            event.route === '/health' || event.route === '/openapi.json' || event.route?.startsWith('/docs') === true,
        },
      },
      metrics: false,
    })),
    // Loads .env files then the environment, and validates every @Config class before anything
    // is created: a missing ADMIN_API_KEY stops the boot with every problem listed (ZNIGHT006).
    ConfigPlugin.configure(),
    HttpPlugin.configure(container => httpOptions(container.get(ServerConfig))),
    OpenApiPlugin.configure(container => openApiOptions(container.get(ServerConfig), document)),
  ],
  // SIGINT / SIGTERM stop the application gracefully: the HTTP server stops accepting connections
  // and drains in-flight requests (4 s), then providers stop. Keep `timeoutMs` below the grace
  // period of your platform (Kubernetes: 30 s, `docker stop`: 10 s).
  shutdown: { timeoutMs: 8_000, hookTimeoutMs: 5_000 },
})

await app.start()
